<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserProviderAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProviderAccessor trait.
 *
 * Covers null default, string/VO assignment via withProvider,
 * getProvider/provider accessors, and isProviderChanged with/without original.
 */
class UserProviderAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withProvider creates a new instance with the Provider set
     * from a string value, and getProvider returns the primitive string.
     */
    public function testWithProviderFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProviderAccessorUnitTest();

        // Act
        $result = $holder->withProvider('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getProvider());
    }
    /**
     * Asserts that withprovider has access to the value object
     * from a string value, and getProvider returns the primitive string.
     */
    public function testWithProviderFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProviderAccessorUnitTest();

        // Act
        $result = $holder->withProvider('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->provider()->value());
    }
    public function testChangedProvider(): void
    {
        // Arrange
        $holder = new ImplWithUserProviderAccessorUnitTest();
        $original = $holder->withProvider('one');
        $same = $holder->withProvider('one');
        $modified = $holder->withProvider('other');

        // Act
        $unchanged = $holder->isProviderChanged();
        $withSame = $original->isProviderChanged($same);
        $withDiferent = $original->isProviderChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProviderAccessorUnitTest
{
    use UserProviderAccessor;
}
